'use strict';

/* ─── About this file ─────────────────────────────────────────────────────────
 * Shared helpers for the test suite (`npm test`). Tests never touch the real
 * data: anything that writes files runs in a throwaway copy made by
 * makeSandbox(), which is deleted afterwards. No test calls Discord, Telegram,
 * Claude or Voyage — clients are replaced by small fakes.
 * ─────────────────────────────────────────────────────────────────────────── */

// ----- Contents (generated by `npm run index` — do not edit) -----
// L27  Setup
// L30    ROOT
// L32  Sandboxes
// L37    makeSandbox()
// L56  Private functions
// L60    loadPrivate()
// L65      localRequire()
// L70  Fakes
// L74    fakeAnthropic()
// ----- end of contents -----

const fs   = require('fs');
const os   = require('os');
const path = require('path');
const vm   = require('vm');

// ─── Setup ────────────────────────────────────────────────────────────────────

// Project root (the folder above test/).
const ROOT = path.join(__dirname, '..');

// ─── Sandboxes ────────────────────────────────────────────────────────────────

// Copies the given project files into a fresh temp folder (plus any extra files given as
// { relPath: content }) and returns { dir, path(rel), cleanup() }. node_modules is linked, not
// copied, so required packages resolve.
function makeSandbox(files = [], extra = {}) {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'riverbot-test-'));
    for (const rel of files) {
        fs.mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
        fs.copyFileSync(path.join(ROOT, rel), path.join(dir, rel));
    }
    for (const [rel, content] of Object.entries(extra)) {
        fs.mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
        fs.writeFileSync(path.join(dir, rel), content);
    }
    fs.symlinkSync(path.join(ROOT, 'node_modules'), path.join(dir, 'node_modules'), 'junction');
    return {
        dir,
        path: (rel) => path.join(dir, rel),
        // Removes the node_modules link first, so the real node_modules is never deleted through it.
        cleanup: () => { fs.unlinkSync(path.join(dir, 'node_modules')); fs.rmSync(dir, { recursive: true, force: true }); },
    };
}

// ─── Private functions ────────────────────────────────────────────────────────

// Loads a project file and returns the named top-level functions/constants it does not export.
// Reads the file as text and runs it with a private module object — it never starts the bot.
function loadPrivate(rel, names, requireFn = require) {
    const file = path.join(ROOT, rel);
    const src = fs.readFileSync(file, 'utf8') + `\nmodule.exports.__private = { ${names.join(', ')} };`;
    const mod = { exports: {} };
    // Resolves the file's own relative requires from its real folder.
    const localRequire = (p) => requireFn(p.startsWith('.') ? path.join(path.dirname(file), p) : p);
    vm.runInThisContext(`(function (require, module, exports, __dirname, __filename) {${src}\n})`)(localRequire, mod, mod.exports, path.dirname(file), file);
    return mod.exports.__private;
}

// ─── Fakes ────────────────────────────────────────────────────────────────────

// A fake Anthropic client. `reply(request)` returns the text the "model" answers; every
// request is recorded in `calls`.
function fakeAnthropic(reply) {
    const calls = [];
    return {
        calls,
        messages: { create: async (req) => { calls.push(req); return { usage: { input_tokens: 1, output_tokens: 1 }, content: [{ text: await reply(req) }] }; } },
    };
}

module.exports = { ROOT, makeSandbox, loadPrivate, fakeAnthropic };
